import React from 'react';
import Navbar from '../../components/Navbar';

export default function Projects() {
  return (
    <>
      <Navbar />
      <div className="min-h-screen h-screen flex flex-col items-center justify-center page-bg">
        <h1 className="text-3xl font-bold mb-4 text-textPrimary-light dark:text-textPrimary-dark">Projects</h1>
        <p className="text-subtle text-lg">Your projects will appear here.</p>
      </div>
    </>
  );
}
